execFileSync('git',['clone','--shared','--no-checkout',parent.atlas,atlas],{windowsHide:true,stdio:'pipe'});execFileSync('git',['-C',atlas,'read-tree','HEAD'],{windowsHide:true,stdio:'pipe'});
for(const row of parent.sourceRows){assert.equal(hash(parent.atlas+'/'+row.path),row.sha256,row.path);const target=path.resolve(atlas,row.path);assert(target.startsWith(path.resolve(atlas)+path.sep));fs.mkdirSync(path.dirname(target),{recursive:true});fs.copyFileSync(parent.atlas+'/'+row.path,target,fs.constants.COPYFILE_EXCL);}
fs.symlinkSync(parent.atlas+'/node_modules',atlas+'/node_modules','junction');assert.equal(execFileSync('git',['-C',atlas,'rev-parse','HEAD'],{encoding:'utf8',windowsHide:true}).trim(),parent.atlasHead);assert.equal(execFileSync('git',['-C',atlas,'status','--porcelain'],{encoding:'utf8',windowsHide:true}).trim(),'');
fs.writeFileSync(stage+'/PREPARATION.json',JSON.stringify({at:new Date().toISOString(),atlas,parentReceipt:file,parentReceiptSha256:hash(file),atlasHead:parent.atlasHead,atlasTree:parent.atlasTree,sourcePaths:parent.sourcePaths,cleanCommittedBaseline:true,previewChanged:false,installed:false},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({stage,sourcePaths:parent.sourcePaths,head:parent.atlasHead}));
